// Ethereum address derivation for receiving test-USDC payments.
//
// The product needs a destination address for each payment, and it must be
// able to prove the address was generated by the product (not pasted in by
// someone else). So each payment gets its own keypair: a fresh secp256k1 key
// from node:crypto, with the address derived the standard way — the last 20
// bytes of keccak-256 over the uncompressed public key (without its 0x04
// prefix). Only keccak is not in node:crypto, which is the one dependency
// (@noble/hashes, pure JS, no native build).
//
// These keys only ever receive test USDC on a public testnet, and the UI
// says so right next to the address.
"use strict";

const { createECDH } = require("node:crypto");
const { keccak_256 } = require("@noble/hashes/sha3.js");

// A new receiving keypair. `privateKey` and `address` are lowercase hex.
function newReceivingKeys() {
  const ecdh = createECDH("secp256k1");
  ecdh.generateKeys();
  const privateKey = ecdh.getPrivateKey("hex");
  const pub = ecdh.getPublicKey().slice(1); // drop the 0x04 uncompressed prefix
  const address = "0x" + Buffer.from(keccak_256(pub)).slice(12).toString("hex");
  return { privateKey, address };
}

// The address that belongs to a private key — used to re-derive the address
// of a stored keypair on boot without trusting the file blindly.
function addressForPrivateKey(privateKeyHex) {
  const ecdh = createECDH("secp256k1");
  const key = Buffer.from(String(privateKeyHex), "hex");
  if (key.length !== 32) return null;
  ecdh.setPrivateKey(key);
  const pub = ecdh.getPublicKey().slice(1);
  return "0x" + Buffer.from(keccak_256(pub)).slice(12).toString("hex");
}

module.exports = { newReceivingKeys, addressForPrivateKey };
